import { Component, Input, SimpleChanges } from '@angular/core';
import { Carrito} from 'src/app/models/carrito';
import { CarritoService } from 'src/app/services/carrito.service';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-carrito',
  templateUrl: './carrito.component.html',
  styleUrls: ['./carrito.component.css']
})
export class CarritoComponent {
  public carrito: Carrito = new Carrito;
  public array: any[] = [];
  @Input() emailUsuario : string;
  public carritoSubscription: Subscription;

  constructor(public carritoService: CarritoService) {
    this.carritoSubscription = this.carritoService.carritoSeleccionado$.subscribe( //nos subscribimos al carrito en el constructor para ver cada vez que cambie
      carritoActualizado => {
        this.carrito = carritoActualizado;
      }
    );
    this.emailUsuario="";
   }

   ngOnInit(): void {
    this.conseguirCarrito("null");
    
   }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['emailUsuario'].currentValue) {
      let email = changes['emailUsuario'].currentValue;
      console.log('Nuevo email de usuario carrito:', email);
      this.emailUsuario = email;
      this.conseguirCarrito(this.emailUsuario);
    }

  }
  conseguirCarrito(email: string){
    this.carritoService.obtenerCarrito(email).subscribe(
      (res: any) => { 
        this.carrito = res;
        this.array = this.carrito.productos;
        //this.carritoService.actualizarCarritoSeleccionado(this.carrito);
        console.log(this.array);
      },
      error => { console.error('Error: ', error); }
    );
  }

  eliminarProducto(nomProducto: string){
    this.carritoService.eliminarProducto(nomProducto, this.emailUsuario).subscribe(
      (res: any) => {
        console.log(res);
        this.carritoService.actualizarCarritoSeleccionado(res);
      },
      error => { console.error('Error: ', error); })
  }
  
  sumarProducto(nomProducto: string, cantidad: number){
    this.carritoService.sumarProducto(nomProducto, this.emailUsuario).subscribe(
      (res: any) => {
        console.log(res);
        this.carritoService.actualizarCarritoSeleccionado(res);
      },
      error => { console.error('Error: ', error); })
  }

  restarProducto(nomProducto: string, cantidad: number){
    this.carritoService.restarProducto(nomProducto, this.emailUsuario).subscribe(
      (res: any) => {
        console.log(res);
        this.carritoService.actualizarCarritoSeleccionado(res);
      },
      error => { console.error('Error: ', error); })
  }

  comprar(){
    //tenemos que vaciar el carrito una vez pase la información a mis compras
  }

  ngOnDestroy() {
    if (this.carritoSubscription) {
      this.carritoSubscription.unsubscribe();
    }
  }

}
<div class="card">
  <div class="card-body">
    <h5 class="card-title">Carrito de compras <i class="bi bi-cart" style="font-size: 24px; margin: 0 10px;"></i></h5>
    
    <div *ngFor="let producto of carrito.productos">
      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px;">
        <div>
          <h6 class="card-subtitle text-muted">{{producto.nombreProd}}</h6>
          <p class="card-text" style="font-size: 12px;">Precio: {{producto.precio}} €</p>
        </div>
        <div style="display: flex; align-items: center;">
          <!--<input type="number" max="{{producto.stock}}" min="1" value="1" style="margin: 10px;"> -->
          <button class="btn btn-danger" (click)="restarProducto(producto.nombreProd, producto.cantidad)">-</button>
          <p class="card-text">Unidades: {{producto.cantidad}}</p>
          <button class="btn btn-success" (click)="sumarProducto(producto.nombreProd, producto.cantidad)">+</button>
          <p class="card-text" style="cursor: pointer; margin-left: 10px;" (click)="eliminarProducto(producto.nombreProd)">❌</p>
        </div>
      </div>
    </div>

    <p class="card-text" id="ptotal" style="font-size: 16px;">Total: {{carrito.total}} €</p>
    <a href="#" class="btn btn-success" (click)="comprar()">Comprar💲</a>
  </div>
</div>
